from collections import deque
def flood(g):
    h,w=len(g),len(g[0])
    seen=set()
    for i in range(h):
        for j in range(w):
            if i in(0,h-1) or j in(0,w-1):
                if g[i][j]==0 and (i,j) not in seen:
                    seen.add((i,j)); q=deque([(i,j)]); seen.discard(None)
    return None
def solve(d,g):
    h,w=len(d),len(d[0])
    blocked={(i,j) for i in range(h) for j in range(w) if d[i][j]!=0}
    seen=set()
    from collections import deque
    start=[(i,j) for i in range(h) for j in range(w) if g[i][j]==0 and ((i==0)or(i==h-1)or(j==0)or(j==w-1))]
    q=deque(start)
    while q:
        i,j=q.popleft()
        for di in(-1,0,1):
            for dj in(-1,0,1):
                ni,nj=i+di,j+dj
                if 0<=ni<h and 0<=nj<w and (ni,nj) not in blocked and (ni,nj) not in seen:
                    seen.add((ni,nj)); q.append((ni,nj))
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==0 and (i,j) not in seen: out[i][j]=2
    return out
